    }

    if (query?.queue) {
      parts.push(`on "${query.queue}"`)
    }

    if (query?.payload !== undefined) {
      parts.push('with matching payload')
    }

    if (query?.delay !== undefined) {
      parts.push('with matching delay')
    }

    const suffix = this.#pushedJobs.length
