  }

  #isJobClass(matcher: FakeJobMatcher): matcher is JobClass {
    return typeof matcher === 'function' && matcher.prototype instanceof Job
  }

  #getJobClassName(JobClass: JobClass): string {
    return JobClass.options?.name || JobClass.name
  }
}
