    if (obj) {
      return console.log(message, obj)
    }

    console.log(message)
  }

  debug(msg: string): void
  debug(obj: LogObject, msg: string): void
  debug(msgOrObj: string | LogObject, msg?: string): void {
    const [message, obj] = this.#format('DEBUG', msgOrObj, msg)

    if (obj) {
