  constructor(data: ScheduleData) {
    this.#data = data
  }

  get id(): string {
    return this.#data.id
  }

  get name(): string {
    return this.#data.name
  }

  get payload(): unknown {
    return this.#data.payload
  }

  get cronExpression(): string | null {
    return this.#data.cronExpression
  }

  get everyMs(): number | null {
    return this.#data.everyMs
  }

  get timezone(): string {
    return this.#data.timezone
  }

  get from(): Date | null {
    return this.#data.from
  }

  get to(): Date | null {
    return this.#data.to
  }

  get limit(): number | null {
    return this.#data.limit
  }

  get runCount(): number {
    return this.#data.runCount
  }

  get nextRunAt(): Date | null {
    return this.#data.nextRunAt
  }

  get lastRunAt(): Date | null {
    return this.#data.lastRunAt
  }

  get status(): ScheduleStatus {
    return this.#data.status
  }

  get createdAt(): Date {
    return this.#data.createdAt
  }

  /**
   * Find a schedule by ID.
   *
   * @param id - The schedule ID
   * @returns The schedule instance, or null if not found
   */
  static async find(id: string): Promise<Schedule | null> {
    const adapter = QueueManager.use()
    const data = await adapter.getSchedule(id)

    if (!data) return null

    return new Schedule(data)
  }

  /**
   * List all schedules matching the given options.
   *
   * @param options - Optional filters for listing
   * @returns Array of schedule instances
   */
  static async list(options?: ScheduleListOptions): Promise<Schedule[]> {
    const adapter = QueueManager.use()
    const schedules = await adapter.listSchedules(options)

    return schedules.map((data) => new Schedule(data))
  }

  /**
   * Pause this schedule.
   * No jobs will be dispatched while paused.
   */
  async pause(): Promise<void> {
    const adapter = QueueManager.use()
    await adapter.updateSchedule(this.#data.id, { status: 'paused' })
    this.#data.status = 'paused'
  }

  /**
   * Resume this schedule.
   * Jobs will be dispatched according to the schedule.
   */
  async resume(): Promise<void> {
    const adapter = QueueManager.use()
    await adapter.updateSchedule(this.#data.id, { status: 'active' })
    this.#data.status = 'active'
  }

  /**
   * Delete this schedule permanently.
   */
  async delete(): Promise<void> {
    const adapter = QueueManager.use()
    await adapter.deleteSchedule(this.#data.id)
  }

  /**
   * Trigger immediate execution of this schedule's job.
   * Also updates runCount and lastRunAt.
   *
   * If the schedule has reached its limit, the job will not be dispatched.
   *
   * @param payload - Optional custom payload for the job
   */
  async trigger(payload?: any): Promise<void> {
    // Check if limit is reached
    if (this.#data.limit !== null && this.#data.runCount >= this.#data.limit) {
      return
    }

    const adapter = QueueManager.use()

    // Dispatch the job
    const dispatcher = new JobDispatcher(this.#data.name, payload ?? this.#data.payload)
    await dispatcher.run()

    // Update run metadata
    const now = new Date()
    const newRunCount = this.#data.runCount + 1

    await adapter.updateSchedule(this.#data.id, {
      runCount: newRunCount,
      lastRunAt: now,
    })

    this.#data.runCount = newRunCount
    this.#data.lastRunAt = now
  }
}
","import type { Knex } from 'knex'

export class QueueSchemaService {
  #connection: Knex

  constructor(connection: Knex) {
    this.#connection = connection
  }

  /**
   * Creates the jobs table with the default schema.
   * The optional callback allows adding custom columns.
   */
  async createJobsTable(
    tableName: string = 'queue_jobs',
    extend?: (table: Knex.CreateTableBuilder) => void
  ): Promise<void> {
    await this.#connection.schema.createTable(tableName, (table) => {
      table.string('id', 255).notNullable()
      table.string('queue', 255).notNullable()
      table.enu('status', ['pending', 'active', 'delayed', 'completed', 'failed']).notNullable()
      table.text('data').notNullable()
      table.bigint('score').unsigned().nullable()
      table.string('worker_id', 255).nullable()
      table.bigint('acquired_at').unsigned().nullable()
      table.bigint('execute_at').unsigned().nullable()
      table.bigint('finished_at').unsigned().nullable()
      table.text('error').nullable()
      table.string('dedup_id', 510).nullable()
      table.bigint('dedup_at').unsigned().nullable()
      table.bigint('dedup_ttl').unsigned().nullable()
      table.primary(['id', 'queue'])
      table.index(['queue', 'status', 'score'])
      table.index(['queue', 'status', 'execute_at'])
      table.index(['queue', 'status', 'finished_at'])
      table.index(['queue', 'dedup_id'])

      extend?.(table)
    })

    await this.#createDedupActiveUniqueIndex(tableName)
  }

  /**
   * Idempotent migration: adds dedup columns (dedup_id, dedup_at, dedup_ttl)
   * and a (queue, dedup_id) index to an existing jobs table.
   *
   * Safe to run multiple times. Uses hasColumn checks so it won't fail on re-runs.
   * For large Postgres tables, consider pausing workers during the run.
   */
  async addDedupColumns(tableName: string = 'queue_jobs'): Promise<void> {
    const hasDedupId = await this.#connection.schema.hasColumn(tableName, 'dedup_id')
    const hasDedupAt = await this.#connection.schema.hasColumn(tableName, 'dedup_at')
    const hasDedupTtl = await this.#connection.schema.hasColumn(tableName, 'dedup_ttl')

    if (!hasDedupId || !hasDedupAt || !hasDedupTtl) {
      await this.#connection.schema.alterTable(tableName, (table) => {
        if (!hasDedupId) table.string('dedup_id', 510).nullable()
        if (!hasDedupAt) table.bigint('dedup_at').unsigned().nullable()
        if (!hasDedupTtl) table.bigint('dedup_ttl').unsigned().nullable()
      })
    }

    if (!hasDedupId) {
      await this.#connection.schema.alterTable(tableName, (table) => {
        table.index(['queue', 'dedup_id'])
      })
    }

    await this.#createDedupActiveUniqueIndex(tableName)
  }

  /**
   * Partial unique index on (queue, dedup_id) for active dedup slots.
   * Prevents two concurrent inserts with the same dedup_id from both succeeding.
   * Only PG and SQLite support partial unique indexes; MySQL is skipped.
   */
  async #createDedupActiveUniqueIndex(tableName: string): Promise<void> {
    const client = this.#connection.client.config.client
    if (client !== 'pg' && client !== 'better-sqlite3' && client !== 'sqlite3') return

    const indexName = `${tableName}_dedup_active_uidx`
    await this.#connection.raw(
      `CREATE UNIQUE INDEX IF NOT EXISTS ?? ON ?? ("queue", "dedup_id") ` +
        `WHERE "dedup_id" IS NOT NULL AND "status" IN ('pending', 'delayed')`,
      [indexName, tableName]
    )
  }

  /**
   * Creates the schedules table with the default schema.
   * The optional callback allows adding custom columns.
   */
  async createSchedulesTable(
    tableName: string = 'queue_schedules',
    extend?: (table: Knex.CreateTableBuilder) => void
  ): Promise<void> {
    await this.#connection.schema.createTable(tableName, (table) => {
      table.string('id', 255).primary()
      table.string('status', 50).notNullable().defaultTo('active')
      table.string('name', 255).notNullable()
      table.text('payload').notNullable()
      table.string('cron_expression', 255).nullable()
      table.bigint('every_ms').unsigned().nullable()
      table.string('timezone', 100).notNullable().defaultTo('UTC')
      table.timestamp('from_date').nullable()
      table.timestamp('to_date').nullable()
      table.integer('run_limit').unsigned().nullable()
      table.integer('run_count').unsigned().notNullable().defaultTo(0)
      table.timestamp('next_run_at').nullable()
      table.timestamp('last_run_at').nullable()
      table.timestamp('created_at').notNullable().defaultTo(this.#connection.fn.now())
      table.index(['status', 'next_run_at'])

      extend?.(table)
    })
  }

  /**
   * Drops the jobs table if it exists.
   */
  async dropJobsTable(tableName: string = 'queue_jobs'): Promise<void> {
    await this.#connection.schema.dropTableIfExists(tableName)
  }

  /**
   * Drops the schedules table if it exists.
   */
  async dropSchedulesTable(tableName: string = 'queue_schedules'): Promise<void> {
    await this.#connection.schema.dropTableIfExists(tableName)
  }
}
","import type { BackoffConfig, Duration } from '../types/main.js'
import * as errors from '../exceptions.js'
import { parse } from '../utils.js'
import { RuntimeException } from '@poppinss/utils/exception'
import { assertUnreachable } from '@poppinss/utils/assert'

/**
 * Calculates retry delays using configurable strategies.
 *
 * Supports three built-in strategies:
 * - `exponential`: Delay doubles each attempt (1s, 2s, 4s, 8s, ...)
 * - `linear`: Delay increases linearly (5s, 10s, 15s, 20s, ...)
 * - `fixed`: Same delay every time (10s, 10s, 10s, ...)
 *
 * All strategies support:
 * - `maxDelay`: Cap the maximum delay
 * - `jitter`: Add randomness to prevent thundering herd
 *
 * @example
 * ```typescript
 * const strategy = new BackoffStrategy({
 *   strategy: 'exponential',
 *   baseDelay: '1s',
 *   maxDelay: '5m',
 *   multiplier: 2,
 *   jitter: true,
 * })
 *
 * strategy.calculateDelay(1) // ~1000ms
 * strategy.calculateDelay(2) // ~2000ms
 * strategy.calculateDelay(3) // ~4000ms
 * ```
 */
export class BackoffStrategy {
  readonly #config: BackoffConfig

  /**
   * Create a new backoff strategy.
   *
   * @param config - Backoff configuration
   * @throws {E_INVALID_BASE_DELAY} If baseDelay is not positive
   * @throws {E_INVALID_MAX_DELAY} If maxDelay is invalid
   * @throws {E_INVALID_MULTIPLIER} If multiplier is invalid
   */
  constructor(config: BackoffConfig) {
    this.#config = config
    this.#validateConfig()
  }

  /**
   * Calculate the delay for a given attempt number.
   *
   * @param attempt - The attempt number (1-based)
   * @returns Delay in milliseconds
   * @throws {RuntimeException} If attempt is less than 1
   *
   * @example
   * ```typescript
   * // Exponential: 1s, 2s, 4s, 8s, 16s, ...
   * strategy.calculateDelay(1) // 1000
   * strategy.calculateDelay(2) // 2000
   * strategy.calculateDelay(3) // 4000
   * ```
   */
  calculateDelay(attempt: number): number {
    if (attempt < 1) {
      throw new RuntimeException('Attempt number must be >= 1')
    }

    const baseDelayMs = parse(this.#config.baseDelay)
    const maxDelayMs = this.#config.maxDelay ? parse(this.#config.maxDelay) : Infinity
    const multiplier = this.#config.multiplier ?? 2

    let delay: number

    switch (this.#config.strategy) {
      case 'exponential':
        delay = baseDelayMs * Math.pow(multiplier, attempt - 1)
        break
      case 'linear':
        delay = baseDelayMs * attempt
        break
      case 'fixed':
        delay = baseDelayMs
        break
      default:
        assertUnreachable(this.#config.strategy)
    }

    // Apply max delay limit
    delay = Math.min(delay, maxDelayMs)

    if (this.#config.jitter) {
      delay = this.#applyJitter(delay)
    }

    return Math.floor(delay)
  }

  /**
   * Get the Date when the next retry should occur.
   *
   * @param attempt - The attempt number (1-based)
   * @returns Date for the next retry
   *
   * @example
   * ```typescript
   * const nextRetry = strategy.getNextRetryAt(3)
   * console.log(`Retry at: ${nextRetry.toISOString()}`)
   * ```
   */
  getNextRetryAt(attempt: number): Date {
    const delay = this.calculateDelay(attempt)
    return new Date(Date.now() + delay)
  }

  /**
   * Get a frozen copy of the configuration.
   *
   * @returns Readonly configuration object
   */
  getConfig(): Readonly<BackoffConfig> {
    return Object.freeze({ ...this.#config })
  }

  #validateConfig() {
    const baseDelayMs = parse(this.#config.baseDelay)

    if (baseDelayMs <= 0) {
      throw new errors.E_INVALID_BASE_DELAY([
        'Base delay must be a positive integer greater than zero',
      ])
    }

    if (this.#config.maxDelay) {
      const maxDelayMs = parse(this.#config.maxDelay)

      if (maxDelayMs <= 0) {
        throw new errors.E_INVALID_MAX_DELAY([
          'Max delay must be a positive integer greater than zero',
        ])
      }

      if (maxDelayMs <= baseDelayMs) {
        throw new errors.E_INVALID_MAX_DELAY(['Max delay should be greater than base delay'])
      }
    }

    if (this.#config.multiplier !== undefined) {
      if (this.#config.multiplier <= 0) {
        throw new errors.E_INVALID_MULTIPLIER([
          'Multiplier must be a positive number greater than zero',
        ])
      }

      if (this.#config.strategy === 'exponential' && this.#config.multiplier < 1) {
        throw new errors.E_INVALID_MULTIPLIER(['Exponential strategy multiplier should be >= 1'])
      }
    }
  }

  #applyJitter(delay: number): number {
    const jitterRange = delay * 0.25
    const jitter = (Math.random() - 0.5) * 2 * jitterRange

    return Math.max(0, delay + jitter)
  }
}

/**
 * Create an exponential backoff strategy factory.
 *
 * Delay doubles with each attempt: 1s → 2s → 4s → 8s → ...
 *
 * Default config:
 * - baseDelay: 1s
 * - maxDelay: 5m
 * - multiplier: 2
 * - jitter: true
 *
 * @param config - Optional overrides for default config
 * @returns Factory function for creating BackoffStrategy instances
 *
 * @example
 * ```typescript
 * const config = {
 *   retry: {
 *     maxRetries: 5,
 *     backoff: exponentialBackoff({ baseDelay: '500ms', maxDelay: '1m' }),
 *   },
 * }
 * ```
 */
export function exponentialBackoff(config?: Partial<Omit<BackoffConfig, 'strategy'>>) {
  return () =>
    new BackoffStrategy({
      strategy: 'exponential',
      baseDelay: '1s',
      maxDelay: '5m',
      multiplier: 2,
      jitter: true,
      ...config,
    })
